export class AccessCodeGenerator {
 generateAccessCode(seed: string): string {
  return seed.slice(0, 8)
 }
}

@Component
struct ActivityPane {
 @State activities: string[] = []
 build() {
  Column() {
   List() {
    ForEach(this.activities, (activity: string) => {
     ListItem() { Text(activity) }
    })
   }.listDirection(Axis.Vertical).height('100%')
  }
 }
}

